49	/**
50	 * Hoodie table sink.
51	 */
52	public class HoodieTableSink implements AppendStreamTableSink<RowData>, PartitionableTableSink {
53	
54	  private final Configuration conf;
55	  private final TableSchema schema;
56	  private final boolean isBounded;
57	
58	  public HoodieTableSink(Configuration conf, TableSchema schema, boolean isBounded) {
59	    this.conf = conf;
60	    this.schema = schema;
61	    this.isBounded = isBounded;
62	  }
63	
64	  @Override
65	  public DataStreamSink<?> consumeDataStream(DataStream<RowData> dataStream) {
66	    // Read from kafka source
67	    RowType rowType = (RowType) this.schema.toRowDataType().notNull().getLogicalType();
68	    int numWriteTasks = this.conf.getInteger(FlinkOptions.WRITE_TASKS);
69	    StreamWriteOperatorFactory<HoodieRecord> operatorFactory = new StreamWriteOperatorFactory<>(conf, isBounded);
70	
71	    DataStream<Object> pipeline = dataStream
72	        .map(new RowDataToHoodieFunction<>(rowType, conf), TypeInformation.of(HoodieRecord.class))
73	        // Key-by partition path, to avoid multiple subtasks write to a partition at the same time
74	        .keyBy(HoodieRecord::getPartitionPath)
75	        .transform(
76	            "bucket_assigner",
77	            TypeInformation.of(HoodieRecord.class),
78	            new KeyedProcessOperator<>(new BucketAssignFunction<>(conf)))
79	        .uid("uid_bucket_assigner")
80	        // shuffle by fileId(bucket id)
81	        .keyBy(record -> record.getCurrentLocation().getFileId())
82	        .transform("hoodie_stream_write", TypeInformation.of(Object.class), operatorFactory)
83	        .uid("uid_hoodie_stream_write")
84	        .setParallelism(numWriteTasks);
85	    if (StreamerUtil.needsScheduleCompaction(conf)) {
86	      return pipeline.transform("compact_plan_generate",
87	          TypeInformation.of(CompactionPlanEvent.class),
88	          new CompactionPlanOperator(conf))
89	          .uid("uid_compact_plan_generate")
90	          .setParallelism(1) // plan generate must be singleton
91	          .keyBy(event -> event.getOperation().hashCode())
92	          .transform("compact_task",
93	              TypeInformation.of(CompactionCommitEvent.class),
94	              new KeyedProcessOperator<>(new CompactFunction(conf)))
95	          .addSink(new CompactionCommitSink(conf))
96	          .name("compact_commit")
97	          .setParallelism(1); // compaction commit should be singleton
98	    } else {
99	      return pipeline.addSink(new DummySinkFunction<>())
100	          .name("dummy").uid("uid_dummy");
101	    }
102	  }
103	
104	  @Override
105	  public TableSink<RowData> configure(String[] strings, TypeInformation<?>[] infos) {
106	    return this;
107	  }
108	
109	  @Override
110	  public TableSchema getTableSchema() {
111	    return this.schema;
112	  }
113	
114	  @Override
115	  public DataType getConsumedDataType() {
116	    return this.schema.toRowDataType().bridgedTo(RowData.class);
117	  }
118	
119	  @Override
120	  public void setStaticPartition(Map<String, String> partitions) {
121	    // no operation
122	  }
123	
124	  // Dummy sink function that does nothing.
125	  private static class DummySinkFunction<T> implements SinkFunction<T> {}
126	}
